beforeExample:
public class Example {
    public static void main(String[] args) {
        Character cObject = 'a';
        char c1 = cObject.charValue();

        Integer iObject = 10;
        int i1 = iObject.intValue();

        Boolean bObject = true;
        boolean b1 = bObject.booleanValue();

        // This should not be touched by the rule, as 'num' is of type Number
        Number num = Integer.valueOf(5);
        int val = num.intValue();
    }
}

