    }
}

negativeExample:
public class Example {
    public static void main(String[] args) {
        // $x is of type Number, not Integer or Character, so the instanceof guard prevents matching.
        Number num = Integer.valueOf(5);
        int val = num.intValue();

        // This is not a wrapper primitiveValue() call, so it should not be matched.
        java.util.concurrent.atomic.AtomicInteger atomicInt = new java.util.concurrent.atomic.AtomicInteger(0);
        int current = atomicInt.intValue();
    }
}
